fn needs_swap(keys: &[str], vals: &[i64], j: i64) -> bool {
    if j <= 0 { return false }
    let a = j - 1
    if vals[a] < vals[j] { return true }
    if vals[a] == vals[j] { return str_cmp(keys[a], keys[j]) > 0 }
    false
}

fn main() -> i64 {
    let text = match read_file("./data/counts.csv") {
        Ok(t) => t
        Err(e) => {
            eprintln("cannot read: {e}")
            return 2
        }
    }
    let keys: [str] = []
    let vals: [i64] = []
    let lines = str_split(text, "\n")
    for li in 0..len(lines) {
        let line = str_trim(lines[li])
        if len(line) > 0 {
            let parts = str_split(line, ",")
            let v = match parse_int(str_trim(parts[1])) {
                Ok(n) => n
                Err(e) => {
                    eprintln("bad value: {e}")
                    return 1
                }
            }
            keys = arr_push(keys, str_trim(parts[0]))
            vals = arr_push(vals, v)
        }
    }
    let n = len(keys)
    for i in 1..n {
        let j = i
        while needs_swap(&keys, &vals, j) {
            let a = j - 1
            let tk = keys[a]
            keys[a] = keys[j]
            keys[j] = tk
            let tv = vals[a]
            vals[a] = vals[j]
            vals[j] = tv
            j = j - 1
        }
    }
    let out = str_join(keys, ",") + "\n"
    match write_file("./out/answer.txt", out) {
        Ok(_) => 0
        Err(e) => {
            eprintln("cannot write: {e}")
            1
        }
    }
}

